<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --chatgpt: #10A37F;
    --claude: #D4A843;
    --gemini: #4285F4;
    --copilot: #00B4D8;
    --perplexity: #A855F7;
    --bg: #0F1117;
    --surface: #1A1D27;
    --surface2: #22263A;
    --border: #2E3250;
    --text: #E8EAF0;
    --text-muted: #8B91B0;
    --accent: #6C72FF;
    --positive: #22C55E;
    --negative: #EF4444;
    --warning: #F59E0B;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg);
    color: var(--text);
