  }
  .report-meta { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); margin-bottom: 16px; }
  h1 { font-size: 32px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.2; margin-bottom: 14px; }
  h1 span { color: var(--accent); }
  .report-subtitle { color: var(--text-muted); font-size: 15px; max-width: 640px; }
  .report-stats-bar {
    display: flex; gap: 32px; margin-top: 36px; padding-top: 28px;
