  }
  .stat-pill { display: flex; flex-direction: column; }
  .stat-pill .val { font-size: 22px; font-weight: 700; color: var(--text); }
  .stat-pill .lbl { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; margin-top: 2px; }

  /* ── LAYOUT ── */
  .content { max-width: 1200px; margin: 0 auto; padding: 48px 64px; }
  @media (max-width: 900px) { .content { padding: 32px 24px; } .report-header { padding: 40px 24px; } }

  /* ── SECTIONS ── */
  .section { margin-bottom: 64px; }
  .section-label { font-size: 10px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--accent); margin-bottom: 10px; }
  h2 { font-size: 22px; font-weight: 700; margin-bottom: 6px; }
  .section-desc { color: var(--text-muted); font-size: 13px; margin-bottom: 28px; max-width: 760px; }
  h3 { font-size: 16px; font-weight: 600; margin-bottom: 14px; color: var(--text); }

  /* ── CARDS ── */
  .card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 24px; }
  .card-grid { display: grid; gap: 20px; }
  .card-grid-2 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-3 { grid-template-columns: repeat(3, 1fr); }
  .card-grid-5 { grid-template-columns: repeat(5, 1fr); }
  @media (max-width: 900px) {
    .card-grid-2, .card-grid-3, .card-grid-5 { grid-template-columns: 1fr; }
  }

  /* ── EXECUTIVE TAKEAWAYS ── */
  .takeaway-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 32px; }
  @media (max-width: 900px) { .takeaway-grid { grid-template-columns: 1fr; } }
  .takeaway {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 22px 20px;
    position: relative;
    overflow: hidden;
  }
  .takeaway::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0; height: 3px;
  }
  .takeaway.t1::before { background: var(--accent); }
  .takeaway.t2::before { background: var(--positive); }
  .takeaway.t3::before { background: var(--warning); }
  .takeaway-num { font-size: 11px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 10px; }
  .takeaway-title { font-size: 15px; font-weight: 700; margin-bottom: 8px; }
  .takeaway-body { font-size: 13px; color: var(--text-muted); line-height: 1.6; }

  /* ── APP BADGES ── */
  .app-badge { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 600; letter-spacing: 0.5px; }
