  .badge-claude { background: rgba(212,168,67,0.15); color: var(--claude); }
  .badge-gemini { background: rgba(66,133,244,0.15); color: var(--gemini); }
  .badge-copilot { background: rgba(0,180,216,0.15); color: var(--copilot); }
  .badge-perplexity { background: rgba(168,85,247,0.15); color: var(--perplexity); }

