  .kpi-card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 20px 24px; }
  .kpi-app { font-size: 12px; font-weight: 600; margin-bottom: 8px; display: flex; align-items: center; gap: 8px; }
  .kpi-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
  .kpi-main { font-size: 28px; font-weight: 700; }
  .kpi-sub { font-size: 12px; color: var(--text-muted); margin-top: 3px; }
  .kpi-bar-wrap { margin-top: 14px; }
  .kpi-bar { height: 6px; border-radius: 3px; background: var(--surface2); overflow: hidden; }
  .kpi-bar-fill { height: 100%; border-radius: 3px; }

  /* ── CHART CONTAINERS ── */
  .chart-wrap { position: relative; }
  .chart-title { font-size: 13px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 16px; }

  /* ── TABLES ── */
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th { text-align: left; padding: 10px 14px; font-size: 10px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--text-muted); border-bottom: 1px solid var(--border); font-weight: 600; }
  td { padding: 12px 14px; border-bottom: 1px solid rgba(46,50,80,0.5); vertical-align: middle; }
  tr:last-child td { border-bottom: none; }
  tr:hover td { background: rgba(255,255,255,0.02); }
  .num { font-variant-numeric: tabular-nums; }
  .rank { font-size: 11px; color: var(--text-muted); font-weight: 600; }

  /* ── DIVERGENCE BAR ── */
  .div-bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
  .div-label { width: 130px; font-size: 12px; flex-shrink: 0; }
  .div-bar-track { flex: 1; height: 22px; background: var(--surface2); border-radius: 4px; overflow: hidden; position: relative; }
  .div-bar-fill { height: 100%; border-radius: 4px; display: flex; align-items: center; justify-content: flex-end; padding-right: 8px; font-size: 11px; font-weight: 700; color: rgba(255,255,255,0.9); }
  .div-pct { width: 46px; text-align: right; font-size: 12px; font-weight: 600; }

  /* ── MISMATCH BREAKDOWN ── */
  .mismatch-row { display: flex; gap: 16px; margin-bottom: 14px; align-items: stretch; }
  .mismatch-cell { flex: 1; background: var(--surface2); border-radius: 8px; padding: 14px; }
  .mismatch-cell .sub-label { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); margin-bottom: 6px; }
  .mismatch-cell .sub-val { font-size: 20px; font-weight: 700; }
  .mismatch-cell .sub-desc { font-size: 11px; color: var(--text-muted); margin-top: 4px; }

  /* ── PILLS ROW ── */
  .pill-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
  .pill { border-radius: 20px; padding: 4px 12px; font-size: 12px; font-weight: 500; }
  .pill-pricing { background: rgba(239,68,68,0.15); color: #EF4444; }
  .pill-bugs { background: rgba(245,158,11,0.15); color: #F59E0B; }
  .pill-accuracy { background: rgba(99,102,241,0.15); color: #818CF8; }
  .pill-general { background: rgba(100,116,139,0.15); color: #94A3B8; }

  /* ── RECOMMENDATIONS ── */
  .rec-item { display: flex; gap: 20px; align-items: flex-start; padding: 22px; background: var(--surface2); border-radius: 12px; border: 1px solid var(--border); margin-bottom: 12px; }
  .rec-num { width: 32px; height: 32px; border-radius: 8px; background: var(--accent); display: flex; align-items: center; justify-content: flex-end; flex-shrink: 0; font-size: 14px; font-weight: 800; color: white; justify-content: center; }
  .rec-body h4 { font-size: 15px; font-weight: 700; margin-bottom: 6px; }
  .rec-body p { font-size: 13px; color: var(--text-muted); line-height: 1.6; }
  .rec-priority { margin-top: 8px; }
  .priority-badge { font-size: 10px; padding: 3px 8px; border-radius: 4px; font-weight: 700; letter-spacing: 0.5px; }
  .priority-high { background: rgba(239,68,68,0.15); color: #EF4444; }
  .priority-med { background: rgba(245,158,11,0.15); color: #F59E0B; }
  .priority-low { background: rgba(99,102,241,0.15); color: #818CF8; }

  /* ── DATA NOTE ── */
  .data-note { background: rgba(108,114,255,0.08); border: 1px solid rgba(108,114,255,0.2); border-radius: 8px; padding: 14px 18px; font-size: 12px; color: var(--text-muted); margin-top: 20px; }
  .data-note strong { color: var(--text); }

  /* ── FOOTER ── */
  .report-footer { border-top: 1px solid var(--border); padding: 32px 64px; color: var(--text-muted); font-size: 12px; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px; }

  /* ── LEGEND ── */
  .legend { display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 20px; }
